<script setup lang="ts">
import UiIcon from './UiIcon.vue';
import {computed} from 'vue';
import type {ReviewOptions} from '../api/contracts';
const props=defineProps<{options:ReviewOptions;busy:boolean;grade:number;allocations:Record<string,number>;allocationTotal:number;parent?:boolean}>();
const group=computed(()=>props.options.groups?.find(g=>g.grade===props.grade));
defineEmits<{replay:[];close:[];reinforce:[];grade:[value:number];allocation:[pointId:string,total:number]}>();
</script>
<template><section class="card review-options" aria-labelledby="reviewTitle"><h2 id="reviewTitle"><UiIcon name="mistakes"/> 再练一练</h2><template v-if="!parent"><h3>再做一次</h3><p>共{{options.replay.total}}题 · 原成绩保留</p><p v-if="!options.replay.allowed" class="error" role="alert">{{options.replay.reason}}</p><details><summary>看看要重练的题目</summary><ol class="replay-equations"><li v-for="item in options.replay.items" :key="item.id">{{item.stem}}<small class="muted"> · {{item.grade}}年级 · {{item.pointName}}</small></li></ol></details><p class="muted">答案从空白开始，旧记录保留。</p><div class="two"><button class="secondary" :disabled="busy" @click="$emit('close')">返回选择</button><button class="primary" :disabled="busy||!options.replay.allowed" @click="$emit('replay')">再做一次</button></div></template><h3>练同类题</h3><p class="muted">选择年级和题数（1—100题）。可能遇到做过的题。</p><label for="reinforceGrade">选择练习年级</label><select id="reinforceGrade" :value="grade" :disabled="busy" @change="$emit('grade',Number(($event.target as HTMLSelectElement).value))"><option v-for="g in options.groups" :key="g.grade" :value="g.grade">{{g.grade}}年级</option></select><div v-for="p in group?.points" :key="p.pointId"><label :for="'reinforce-'+p.pointId">{{p.pointName}} · 可用{{p.available}}题</label><input :id="'reinforce-'+p.pointId" type="number" min="1" max="100" step="1" :value="allocations[p.pointId]" :disabled="busy" @input="$emit('allocation',p.pointId,Number(($event.target as HTMLInputElement).value))"><p v-if="p.reason" class="error">{{p.reason}}</p></div><p>本次共 {{allocationTotal}} 题</p><button class="primary" :disabled="busy||!group" @click="$emit('reinforce')">{{parent?'生成强化题目预览':'练同类题'}}</button><button v-if="parent" class="secondary" :disabled="busy" @click="$emit('close')">返回选择</button></section></template>
